mutations.replace:
listChangedSessions: async ({ dbnum, refno, sinceSesno }) => {
  const table = await (await loadModelSource()).getModelSource().versions.listNodeVersions(dbnum, refno, 'subtree', { sinceSesno });
  return table.versions.filter((version) => version.impact !== 'noop').map((version) => ({ sesno: version.sesno, time: version.sessionTime, unitsChanged: version.unitsChanged }));
},

